use rand::Rng;

pub fn genann_randomize(ann: &mut Genann) {
    let mut rng = rand::thread_rng();
    for i in 0..ann.total_weights as usize {
        let r: f64 = rng.gen_range(0.0..1.0);
        ann.weight[i] = r - 0.5;
    }
}

pub fn genann_copy(ann: &Genann) -> Option<Genann> {
    let size = ann.total_weights as usize + ann.total_neurons as usize + (ann.total_neurons - ann.inputs) as usize;

    let mut ret = Genann {
        inputs: ann.inputs,
        hidden_layers: ann.hidden_layers,
        hidden: ann.hidden,
        outputs: ann.outputs,
        activation_hidden: ann.activation_hidden,
        activation_output: ann.activation_output,
        total_weights: ann.total_weights,
        total_neurons: ann.total_neurons,
        weight: Vec::with_capacity(ann.total_weights as usize),
        output: Vec::with_capacity(ann.total_neurons as usize),
        delta: Vec::with_capacity((ann.total_neurons - ann.inputs) as usize),
    };

    ret.weight.extend_from_slice(&ann.weight);
    ret.output.extend_from_slice(&ann.output);
    ret.delta.extend_from_slice(&ann.delta);

    Some(ret)
}

pub fn genann_free(ann: Genann) {
    drop(ann);
}

use std::io::{self, Write};

pub fn genann_write(ann: &Genann, out: &mut dyn Write) -> io::Result<()> {
    writeln!(out, "{} {} {} {}", ann.inputs, ann.hidden_layers, ann.hidden, ann.outputs)?;
    for weight in &ann.weight {
        write!(out, " {:.20e}", weight)?;
    }
    Ok(())
}

pub fn genann_act_sigmoid(_ann: &Genann, a: f64) -> f64 {
    if a < -45.0 {
        return 0.0;
    }
    if a > 45.0 {
        return 1.0;
    }
    1.0 / (1.0 + (-a).exp())
}

pub fn genann_act_sigmoid_cached(ann: &Genann, a: f64) -> f64 {
    assert!(!a.is_nan(), "!isnan(a)");

    if a < SIGMOID_DOM_MIN {
        return LOOKUP[0];
    }
    if a >= SIGMOID_DOM_MAX {
        return LOOKUP[4095];
    }

    let j = ((a - SIGMOID_DOM_MIN) * unsafe { INTERVAL } + 0.5) as usize;
    if j >= 4096 {
        return LOOKUP[4095];
    }
    LOOKUP[j]
}

pub fn genann_act_threshold(ann: &Genann, a: f64) -> f64 {
    if a > 0.0 {
        1.0
    } else {
        0.0
    }
}

pub fn genann_act_linear(ann: &Genann, a: f64) -> f64 {
    a
}

pub fn genann_act_hidden_indirect(ann: &Genann, a: f64) -> f64 {
    (ann.activation_hidden)(ann, a)
}

pub fn genann_act_output_indirect(ann: &Genann, a: f64) -> f64 {
    (ann.activation_output)(ann, a)
}

pub fn genann_init_sigmoid_lookup(ann: &Genann) {
    let f = (SIGMOID_DOM_MAX - SIGMOID_DOM_MIN) / 4096.0;
    unsafe {
        INTERVAL = 4096.0 / (SIGMOID_DOM_MAX - SIGMOID_DOM_MIN);
        for i in 0..4096 {
            LOOKUP[i] = genann_act_sigmoid(ann, SIGMOID_DOM_MIN + f * i as f64);
        }
    }
}

pub fn genann_act_threshold(_ann: &Genann, a: f64) -> f64 {
    if a > 0.0 { 1.0 } else { 0.0 }
}

pub fn genann_act_linear(_ann: &Genann, a: f64) -> f64 {
    a
}

pub fn genann_run(ann: &Genann, inputs: &[f64]) -> &[f64] {
    let mut w = ann.weight.iter();
    let mut o = ann.output[ann.inputs as usize..].iter_mut();
    ann.output[..ann.inputs as usize].copy_from_slice(inputs);
    let mut i = ann.output.iter();

    if ann.hidden_layers == 0 {
        let ret = &ann.output[ann.inputs as usize..];
        for j in 0..ann.outputs {
            let mut sum = *w.next().unwrap() * -1.0;
            for k in 0..ann.inputs {
                sum += *w.next().unwrap() * i.next().unwrap();
            }
            *o.next().unwrap() = genann_act_output_indirect(ann, sum);
        }
        return ret;
    }

    for j in 0..ann.hidden {
        let mut sum = *w.next().unwrap() * -1.0;
        for k in 0..ann.inputs {
            sum += *w.next().unwrap() * i.next().unwrap();
        }
        *o.next().unwrap() = genann_act_hidden_indirect(ann, sum);
    }

    i = i.skip(ann.inputs as usize);

    for h in 1..ann.hidden_layers {
        for j in 0..ann.hidden {
            let mut sum = *w.next().unwrap() * -1.0;
            for k in 0..ann.hidden {
                sum += *w.next().unwrap() * i.next().unwrap();
            }
            *o.next().unwrap() = genann_act_hidden_indirect(ann, sum);
        }
        i = i.skip(ann.hidden as usize);
    }

    let ret = &ann.output[ann.inputs as usize..];
    for j in 0..ann.outputs {
        let mut sum = *w.next().unwrap() * -1.0;
        for k in 0..ann.hidden {
            sum += *w.next().unwrap() * i.next().unwrap();
        }
        *o.next().unwrap() = genann_act_output_indirect(ann, sum);
    }

    assert_eq!(w.len(), ann.total_weights as usize - (w.as_slice().len()));
    assert_eq!(o.len(), ann.total_neurons as usize - (o.as_slice().len()));

    ret
}

use std::vec::Vec;
use std::boxed::Box;

pub struct Genann {
    pub inputs: i32,
    pub hidden_layers: i32,
    pub hidden: i32,
    pub outputs: i32,
    pub activation_hidden: GenannActFun,
    pub activation_output: GenannActFun,
    pub total_weights: i32,
    pub total_neurons: i32,
    pub weight: Vec<f64>,
    pub output: Vec<f64>,
    pub delta: Vec<f64>,
}

pub type GenannActFun = fn(&Genann, f64) -> f64;

pub fn genann_init(inputs: i32, hidden_layers: i32, hidden: i32, outputs: i32) -> Option<Box<Genann>> {
    if hidden_layers < 0 || inputs < 1 || outputs < 1 || (hidden_layers > 0 && hidden < 1) {
        return None;
    }

    let hidden_weights = if hidden_layers > 0 {
        (inputs + 1) * hidden + (hidden_layers - 1) * (hidden + 1) * hidden
    } else {
        0
    };

    let output_weights = if hidden_layers > 0 {
        (hidden + 1) * outputs
    } else {
        (inputs + 1) * outputs
    };

    let total_weights = hidden_weights + output_weights;
    let total_neurons = inputs + hidden * hidden_layers + outputs;

    let mut ret = Box::new(Genann {
        inputs,
        hidden_layers,
        hidden,
        outputs,
        activation_hidden: genann_act_sigmoid_cached,
        activation_output: genann_act_sigmoid_cached,
        total_weights,
        total_neurons,
        weight: vec![0.0; total_weights as usize],
        output: vec![0.0; total_neurons as usize],
        delta: vec![0.0; (total_neurons - inputs) as usize],
    });

    genann_randomize(&mut ret);
    genann_init_sigmoid_lookup(&ret);

    Some(ret)
}

