pub fn genann_train(ann: &Genann, inputs: &[f64], desired_outputs: &[f64], learning_rate: f64) {
    genann_run(ann, inputs);
    let mut h;
    let mut j;
    let mut k;

    {
        let o = &ann.output[(ann.inputs + ann.hidden * ann.hidden_layers) as usize..];
        let d = &mut ann.delta[(ann.hidden * ann.hidden_layers) as usize..];
        let t = desired_outputs;
        if genann_act_output_indirect as usize == genann_act_linear as usize || ann.activation_output as usize == genann_act_linear as usize {
            for j in 0..ann.outputs as usize {
                d[j] = t[j] - o[j];
            }
        } else {
            for j in 0..ann.outputs as usize {
                d[j] = (t[j] - o[j]) * o[j] * (1.0 - o[j]);
            }
        }
    }

    for h in (0..ann.hidden_layers).rev() {
        let o = &ann.output[(ann.inputs + (h * ann.hidden)) as usize..];
        let d = &mut ann.delta[(h * ann.hidden) as usize..];
        let dd = &ann.delta[((h + 1) * ann.hidden) as usize..];
        let ww = &ann.weight[((ann.inputs + 1) * ann.hidden + (ann.hidden + 1) * ann.hidden * h) as usize..];
        for j in 0..ann.hidden as usize {
            let mut delta = 0.0;
            for k in 0..if h == ann.hidden_layers - 1 { ann.outputs } else { ann.hidden } as usize {
                let forward_delta = dd[k];
                let windex = k * (ann.hidden + 1) as usize + (j + 1);
                let forward_weight = ww[windex];
                delta += forward_delta * forward_weight;
            }
            d[j] = o[j] * (1.0 - o[j]) * delta;
        }
    }

    {
        let d = &ann.delta[(ann.hidden * ann.hidden_layers) as usize..];
        let mut w = &mut ann.weight[(if ann.hidden_layers > 0 { (ann.inputs + 1) * ann.hidden + (ann.hidden + 1) * ann.hidden * (ann.hidden_layers - 1) } else { 0 }) as usize..];
        let i = &ann.output[(if ann.hidden_layers > 0 { ann.inputs + ann.hidden * (ann.hidden_layers - 1) } else { 0 }) as usize..];
        for j in 0..ann.outputs as usize {
            w[j] += d[j] * learning_rate * -1.0;
            for k in 1..(if ann.hidden_layers > 0 { ann.hidden } else { ann.inputs } + 1) as usize {
                w[j + k] += d[j] * learning_rate * i[k - 1];
            }
        }
        assert_eq!(w.len(), ann.total_weights as usize, "w - ann.weight == ann.total_weights");
    }

    for h in (0..ann.hidden_layers).rev() {
        let d = &ann.delta[(h * ann.hidden) as usize..];
        let i = &ann.output[(if h > 0 { ann.inputs + ann.hidden * (h - 1) } else { 0 }) as usize..];
        let mut w = &mut ann.weight[(if h > 0 { (ann.inputs + 1) * ann.hidden + (ann.hidden + 1) * ann.hidden * (h - 1) } else { 0 }) as usize..];
        for j in 0..ann.hidden as usize {
            w[j] += d[j] * learning_rate * -1.0;
            for k in 1..(if h == 0 { ann.inputs } else { ann.hidden } + 1) as usize {
                w[j + k] += d[j] * learning_rate * i[k - 1];
            }
        }
    }
}

use std::io::{self, BufRead};
use std::fs::File;
use std::path::Path;

pub struct Genann {
    pub inputs: i32,
    pub hidden_layers: i32,
    pub hidden: i32,
    pub outputs: i32,
    pub activation_hidden: GenannActFun,
    pub activation_output: GenannActFun,
    pub total_weights: i32,
    pub total_neurons: i32,
    pub weight: Vec<f64>,
    pub output: Vec<f64>,
    pub delta: Vec<f64>,
}

pub type GenannActFun = fn(&Genann, f64) -> f64;

pub fn genann_read<P: AsRef<Path>>(path: P) -> io::Result<Genann> {
    let file = File::open(path)?;
    let mut reader = io::BufReader::new(file);

    let mut line = String::new();
    reader.read_line(&mut line)?;
    let mut parts = line.split_whitespace();

    let inputs: i32 = parts.next().ok_or(io::Error::new(io::ErrorKind::InvalidData, "Missing inputs"))?.parse()?;
    let hidden_layers: i32 = parts.next().ok_or(io::Error::new(io::ErrorKind::InvalidData, "Missing hidden_layers"))?.parse()?;
    let hidden: i32 = parts.next().ok_or(io::Error::new(io::ErrorKind::InvalidData, "Missing hidden"))?.parse()?;
    let outputs: i32 = parts.next().ok_or(io::Error::new(io::ErrorKind::InvalidData, "Missing outputs"))?.parse()?;

    let mut ann = genann_init(inputs, hidden_layers, hidden, outputs);

    for i in 0..ann.total_weights as usize {
        line.clear();
        reader.read_line(&mut line)?;
        let weight: f64 = line.trim().parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "Invalid weight"))?;
        ann.weight[i] = weight;
    }

    Ok(ann)
}

pub fn genann_init(inputs: i32, hidden_layers: i32, hidden: i32, outputs: i32) -> Genann {
    let total_weights = (inputs * hidden_layers * hidden + hidden_layers * hidden * outputs) as i32;
    let total_neurons = (inputs + hidden_layers * hidden + outputs) as i32;

    Genann {
        inputs,
        hidden_layers,
        hidden,
        outputs,
        activation_hidden: |_, x| x, // Placeholder function
